package br.com.sistemacardapio.autenticacao;
import java.util.List;import java.util.UUID;import org.springframework.http.HttpStatus;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.web.bind.annotation.*;
@RestController@RequestMapping("/api/usuarios")@PreAuthorize("hasRole('ADMIN_EMPRESA')")public class UsuarioEmpresaController{private final UsuarioAdminService service;public UsuarioEmpresaController(UsuarioAdminService service){this.service=service;}@GetMapping public List<UsuarioAdminService.Response>listar(){return service.listarMinhaEmpresa();}@PostMapping@ResponseStatus(HttpStatus.CREATED)public UsuarioAdminService.Response criar(@RequestBody UsuarioAdminService.Request request){return service.criarNaMinhaEmpresa(request);}@PutMapping("/{id}")public UsuarioAdminService.Response atualizar(@PathVariable UUID id,@RequestBody UsuarioAdminService.UpdateRequest request){return service.atualizarMinhaEmpresa(id,request);}@PutMapping("/{id}/senha")public UsuarioAdminService.Response senha(@PathVariable UUID id,@RequestBody UsuarioAdminService.PasswordRequest request){return service.redefinirMinhaEmpresa(id,request);}}
